// spec: specs/calculator.md (2.8) · кейс: .qa/tests/calculator/CALC-FORM-08.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение. Вставка — через буфер обмена Chromium (desktop, Pixel 7).
import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, field, SET1, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — формулы и крайние случаи', () => {
  for (const tag of DEVICES) {
    test(`«1e5» и вставка «12abc» → «יש להזין מספר בלבד» + aria-invalid #d45b2a ${tag} @prod-safe`, async ({ page, context, baseURL }) => {
      await context.grantPermissions(['clipboard-read', 'clipboard-write'], { origin: new URL(baseURL!).origin });
      await prepareReadOnly(context);
      await openCalculator(page);
      const price = field(page, 'purchasePrice');
      const error = page.locator('#calc-purchasePrice-error');

      await fillInputs(page, { purchasePrice: '1e5' });
      await expect(error).toHaveText('יש להזין מספר בלבד');
      await expect(price).toHaveAttribute('aria-invalid', 'true');

      await fillInputs(page, { purchasePrice: '' });
      await page.evaluate(() => navigator.clipboard.writeText('12abc'));
      await price.click();
      await page.keyboard.press('ControlOrMeta+V');
      await expect(price).toHaveValue('12abc');
      await expect(error).toHaveText('יש להזין מספר בלבד');
      await expect(price).toHaveAttribute('aria-invalid', 'true');
    });

    test(`Минус в «רווח חודשי לפני מס» разрешён — без ошибки, תזרים отрицательный #d45b2a ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);
      await fillInputs(page, { ...SET1, monthlyProfit: '-5000' });

      await expectResult(page, 'מס חודשי משוער', '0 ₪');
      await expectResult(page, 'רווח חודשי לאחר מס', '-20,000 ₪');
      await expectResult(page, 'תזרים חודשי משוער', '-25,000 ₪');
      await expect(field(page, 'monthlyProfit')).toHaveAttribute('aria-invalid', 'false');
      await expect(page.locator('#calc-monthlyProfit-error')).toHaveCount(0);
    });
  }
});
